// Regenerates database/full-schema.sql from src/drizzle/*.sql (in journal order).
// Usage: npm run db:export
import { readFileSync, writeFileSync } from "node:fs";

const journal = JSON.parse(readFileSync("src/drizzle/meta/_journal.json", "utf8"));
const out = [
  "-- GitHub Monitor — full database SQL (all migrations, in order).",
  "-- AUTO-GENERATED by `npm run db:export` from src/drizzle/*.sql — do not edit by hand.",
  "-- Source of truth: src/lib/db/schema.ts. To apply to a database use `npm run db:migrate`.",
  "",
];
for (const { tag } of journal.entries) {
  const sql = readFileSync(`src/drizzle/${tag}.sql`, "utf8").replaceAll("--> statement-breakpoint\n", "");
  out.push(`-- ===== ${tag} =====`, sql.trim(), "");
}
writeFileSync("database/full-schema.sql", out.join("\n"));
console.log(`Wrote database/full-schema.sql (${journal.entries.length} migrations)`);
